type UserDto = { id: number; name: string };
function isUserDto(value: unknown): value is UserDto {
  return typeof value === "object" && value !== null && "id" in value && typeof value.id === "number" && "name" in value && typeof value.name === "string";
}
const candidate: unknown = JSON.parse("{\"id\":1,\"name\":\"Asha\"}");
if (isUserDto(candidate)) console.log(candidate.name);
